fetchDiffs(signal.source, signal.sessionId)
      .then((diffs) => {
        if (cancelled) return;
        const match = diffs.find((diff) =>
          diffMatchesFile(diff.filePath, signal.filePath)
        );
        if (match?.diff) {
          const parsed = parseUnifiedDiffToOldNew(match.diff);
          setState({
            status: "ready",
            oldValue: parsed.oldValue,
            newValue: parsed.newValue,
            oldStartLine: parsed.oldStartLine,
            newStartLine: parsed.newStartLine,
          });
        } else if (
          match &&
          (match.oldContent != null || match.newContent != null)
        ) {
          setState({
            status: "ready",
            oldValue: match.oldContent ?? "",
            newValue: match.newContent ?? "",
          });
        } else {
          setState({ status: "empty" });
        }
      })
      .catch

(async () => {
      let probes: ExternalCliSourceProbe[] = [];
      try {
        probes = await externalCliSourcesDetect();
      } catch {
        if (!cancelled) setRows([]);
        return;
      }
      if (cancelled) return;
      const built: SourceRow[] = probes
        .map((probe) => {
          const importable = probe.importable && isImportableId(probe.sourceId);
          const enabled = getSourceConfig(
            configRef.current,
            probe.sourceId
          ).enabled;
          return {
            probe,
            importable,
            stats: null,
            statsLoading: importable && enabled,
            rescanning: false,
            error: false,
          };
        })
        .sort((a, b) => {
          const rank = (r: SourceRow) =>
            r.importable ? 0 : r.probe.installed ? 1 : 2;
          return (
            rank(a) - rank(b) ||
            a.probe.displayName.localeCompare(b.probe.displayName)
          );
        });
      setRows(built);
      await Promise.all(
        built
          .filter(
            (r) =>
              r.importable &&
              isImportableId(r.probe.sourceId) &&
              getSourceConfig(configRef.current, r.probe.sourceId).enabled
          )
          .map((r) => loadStats(r.probe.sourceId as ImportedHistorySourceId))
      );
    })

